// Face blob v1 / drawing blob v2 codecs, byte-identical to crates/deskbunny-core
// (fixtures: test/fixtures/*.json, generated by crates/deskbunny-core/tests/mobile_fixtures.rs).
import 'dart:typed_data';
import '../model/drawing.dart';
import '../model/face.dart';

const int faceBlobSize = 64;
const int maxArtBytes = 12285; // see ARCHITECTURE.md "ESP32 + BLE"

const List<int> _faceMagic = [0x44, 0x42, 0x46, 0x41, 0x43, 0x45, 0x30, 0x31]; // DBFACE01
const int _faceVersion = 1;
const List<int> _artMagic = [0x44, 0x42, 0x41, 0x52, 0x54, 0x30, 0x30, 0x31]; // DBART001
const int _artVersion = 2;
const int artHeaderSize = 16;

const int _flagBlink = 0x01, _flagLook = 0x02, _flagBreathe = 0x04, _flagCyclops = 0x08;
const int _flagInvert = 0x10, _flagRotate = 0x20, _flagMouth = 0x40;
const int _cycleFlagOverlay = 0x01;

/// CRC-16/CCITT-FALSE (poly 0x1021, init 0xFFFF, no reflection, no xorout).
int crc16(List<int> data, [int start = 0, int? end]) {
  var crc = 0xFFFF;
  for (var i = start; i < (end ?? data.length); i++) {
    crc ^= (data[i] & 0xFF) << 8;
    for (var b = 0; b < 8; b++) {
      crc = (crc & 0x8000) != 0 ? ((crc << 1) ^ 0x1021) & 0xFFFF : (crc << 1) & 0xFFFF;
    }
  }
  return crc;
}

/// The 64-byte blob (normalised first, like `FaceDef::encode`).
Uint8List encodeFace(FaceDef face) {
  final f = face.normalised();
  final b = Uint8List(faceBlobSize);
  b.setRange(0, 8, _faceMagic);
  b[8] = _faceVersion;
  b[9] = f.mood.index;
  final name = f.name.codeUnits;
  for (var i = 0; i < name.length && i < faceNameMax; i++) {
    b[10 + i] = name[i];
  }
  b[22] = f.eyeW;
  b[23] = f.eyeH;
  b[24] = f.eyeR;
  b[25] = f.eyeGap;
  b[26] = f.eyeY & 0xFF;
  b[27] = (f.blink ? _flagBlink : 0) |
      (f.lookAround ? _flagLook : 0) |
      (f.breathe ? _flagBreathe : 0) |
      (f.cyclops ? _flagCyclops : 0) |
      (f.invert ? _flagInvert : 0) |
      (f.rotate180 ? _flagRotate : 0) |
      (f.mouth ? _flagMouth : 0);
  b[28] = f.blinkMin;
  b[29] = f.blinkMax;
  b[30] = f.lookMin;
  b[31] = f.lookMax;
  b[32] = f.lookX;
  b[33] = f.lookY;
  b[34] = f.speed;
  b[35] = f.contrast;
  b[36] = f.overlay.index;
  b[37] = f.seed;
  b[38] = f.cycle.index;
  b[39] = f.cycleSeconds;
  b[40] = f.cycleMoods.length;
  b[41] = f.cycleOverlay ? _cycleFlagOverlay : 0;
  for (var i = 0; i < f.cycleMoods.length; i++) {
    b[42 + i] = f.cycleMoods[i].index;
  }
  final crc = crc16(b, 0, 62);
  b[62] = crc & 0xFF;
  b[63] = crc >> 8;
  return b;
}

/// Decode like `db_face_decode` + `FaceDef::from_raw`: out-of-range fields are
/// clamped (unknown enums -> 0, eye sizes, speed, name charset, cycle list).
/// Throws FormatException on bad length/magic/version/CRC.
FaceDef decodeFace(Uint8List blob) {
  if (blob.length != faceBlobSize) {
    throw FormatException('Face data must be exactly 64 bytes, got ${blob.length}.');
  }
  for (var i = 0; i < 8; i++) {
    if (blob[i] != _faceMagic[i]) {
      throw const FormatException('Face data is not a DeskBunny face (bad magic).');
    }
  }
  if (blob[8] != _faceVersion) throw const FormatException('Face data has an unsupported version.');
  final crc = crc16(blob, 0, 62);
  if (blob[62] != (crc & 0xFF) || blob[63] != (crc >> 8)) {
    throw const FormatException('Face data is corrupted (CRC mismatch).');
  }
  int clamp(int v, int lo, int hi) => v < lo ? lo : (v > hi ? hi : v);

  // face_sanitize in the C engine.
  final name = StringBuffer();
  for (var i = 0; i < faceNameMax; i++) {
    var c = blob[10 + i];
    if (c == 0) break;
    if (c >= 0x61 && c <= 0x7A) c -= 0x20;
    final ok = (c >= 0x41 && c <= 0x5A) || (c >= 0x30 && c <= 0x39) || c == 0x20;
    name.writeCharCode(ok ? c : 0x20);
  }
  final eyeW = clamp(blob[22], 8, 56);
  final eyeR = blob[24] > eyeW ~/ 2 ? eyeW ~/ 2 : blob[24];
  final count = blob[40] > cycleMax ? cycleMax : blob[40];
  final flags = blob[27];
  bool has(int bit) => flags & bit != 0;
  return FaceDef(
    name: name.toString(),
    mood: blob[9] < Mood.values.length ? Mood.values[blob[9]] : Mood.neutral,
    eyeW: eyeW,
    eyeH: clamp(blob[23], 8, 56),
    eyeR: eyeR,
    eyeGap: blob[25] > 40 ? 40 : blob[25],
    eyeY: blob[26] >= 128 ? blob[26] - 256 : blob[26],
    blink: has(_flagBlink),
    lookAround: has(_flagLook),
    breathe: has(_flagBreathe),
    cyclops: has(_flagCyclops),
    invert: has(_flagInvert),
    rotate180: has(_flagRotate),
    mouth: has(_flagMouth),
    blinkMin: blob[28],
    blinkMax: blob[29],
    lookMin: blob[30],
    lookMax: blob[31],
    lookX: blob[32],
    lookY: blob[33],
    speed: clamp(blob[34], 1, 10),
    contrast: blob[35],
    overlay: blob[36] < FaceOverlay.values.length ? FaceOverlay.values[blob[36]] : FaceOverlay.none,
    seed: blob[37],
    cycle: blob[38] < CycleMode.values.length ? CycleMode.values[blob[38]] : CycleMode.off,
    cycleSeconds: blob[39] == 0 ? 10 : blob[39],
    cycleMoods: List.unmodifiable([
      for (var i = 0; i < count; i++)
        blob[42 + i] < Mood.values.length ? Mood.values[blob[42 + i]] : Mood.neutral,
    ]),
    cycleOverlay: blob[41] & _cycleFlagOverlay != 0,
  );
}

/// PackBits: token t < 128 is followed by t + 1 literal bytes; t >= 128 by one
/// byte repeated t - 126 times (2..129). Same output as `pack_into` in drawing.rs.
void _packInto(Uint8List src, BytesBuilder out) {
  var i = 0;
  final lit = <int>[];
  void flush() {
    for (var s = 0; s < lit.length; s += 128) {
      final e = s + 128 < lit.length ? s + 128 : lit.length;
      out.addByte(e - s - 1);
      out.add(lit.sublist(s, e));
    }
    lit.clear();
  }

  while (i < src.length) {
    var run = 1;
    while (i + run < src.length && run < 129 && src[i + run] == src[i]) {
      run++;
    }
    if (run >= 2) {
      flush();
      out.addByte(run + 126);
      out.addByte(src[i]);
      i += run;
    } else {
      lit.add(src[i]);
      i++;
    }
  }
  flush();
}

Uint8List _frameData(Drawing d) {
  final out = BytesBuilder(copy: false);
  var prev = Uint8List(Drawing.frameBytes);
  for (final f in d.frames) {
    if (d.mode == DrawingMode.replace) {
      final delta = Uint8List(Drawing.frameBytes);
      for (var i = 0; i < Drawing.frameBytes; i++) {
        delta[i] = f[i] ^ prev[i];
      }
      _packInto(delta, out);
      prev = f;
    } else {
      _packInto(f, out);
    }
  }
  return out.takeBytes();
}

Uint8List _offBlob() {
  final b = Uint8List(artHeaderSize);
  b.setRange(0, 8, _artMagic);
  b[8] = _artVersion;
  return b;
}

/// Drawing blob v2 (PackBits + XOR deltas). capacity field = 0.
/// Sanitised first; a drawing with no frames encodes as the 16-byte "off" blob.
/// Does not enforce [maxArtBytes]: check [drawingSize] (Bunny.putSlot does).
Uint8List encodeDrawing(Drawing drawing) {
  final d = drawing.sanitized();
  if (d == null) return _offBlob();
  final data = _frameData(d);
  final b = Uint8List(artHeaderSize + data.length);
  b.setRange(0, artHeaderSize, _offBlob());
  b[9] = d.mode == DrawingMode.replace ? 1 : 2;
  b[10] = d.frames.length & 0xFF;
  b[11] = d.frames.length >> 8;
  b[12] = d.frameMs & 0xFF;
  b[13] = d.frameMs >> 8;
  b.setRange(artHeaderSize, b.length, data);
  return b;
}

/// Bytes the drawing takes on the device, header included (`encoded_len`):
/// compare against [maxArtBytes] for the size meter.
int drawingSize(Drawing drawing) {
  final d = drawing.sanitized();
  return d == null ? artHeaderSize : artHeaderSize + _frameData(d).length;
}

/// null when the blob is off/invalid (bad magic, version, mode, frame count,
/// or a stream that runs past the end), as the firmware treats it.
Drawing? decodeDrawing(Uint8List blob) {
  if (blob.length < artHeaderSize) return null;
  for (var i = 0; i < 8; i++) {
    if (blob[i] != _artMagic[i]) return null;
  }
  if (blob[8] != _artVersion) return null;
  final mode = blob[9];
  if (mode != 1 && mode != 2) return null;
  final n = blob[10] | (blob[11] << 8);
  if (n < 1 || n > Drawing.framesMax) return null;
  var ms = blob[12] | (blob[13] << 8);
  ms = ms == 0 ? Drawing.frameMsDefault : ms.clamp(Drawing.frameMsMin, Drawing.frameMsMax);

  final frames = <Uint8List>[];
  final fb = Uint8List(Drawing.frameBytes);
  var p = artHeaderSize;
  for (var k = 0; k < n; k++) {
    if (mode == 2) fb.fillRange(0, Drawing.frameBytes, 0);
    // db_art_frame
    var i = 0;
    while (i < Drawing.frameBytes) {
      if (p >= blob.length) return null;
      final t = blob[p++];
      final run = t >= 128;
      var c = run ? t - 126 : t + 1;
      if (i + c > Drawing.frameBytes) return null;
      var v = 0;
      if (run) {
        if (p >= blob.length) return null;
        v = blob[p++];
      }
      for (; c > 0; c--, i++) {
        if (!run) {
          if (p >= blob.length) return null;
          v = blob[p++];
        }
        if (mode == 1) {
          fb[i] ^= v;
        } else {
          fb[i] |= v;
        }
      }
    }
    frames.add(Uint8List.fromList(fb));
  }
  return Drawing(
    mode: mode == 1 ? DrawingMode.replace : DrawingMode.over,
    frameMs: ms,
    frames: List.unmodifiable(frames),
  );
}
